// Writes a size tier into a copy of the React Native tier shell
// (`arena/apps/react-native/tier`): one TSX component per screen under
// `src/screens/`, and `App.tsx`, which holds the current screen in state and
// renders the home menu or that screen. No navigation library.

import {
	type CounterScreen,
	type DetailScreen,
	type FormScreen,
	type ListScreen,
	quoted,
	type Screen,
	type TierApp,
	type TierEmitter,
} from "../tiers.ts";

const GENERATED =
	"// Generated by scripts/arena/emit/react-native.ts. Do not edit.";

/** `counter001` → `Counter001`: the component and file name. */
function componentName(screen: Screen): string {
	return screen.id[0].toUpperCase() + screen.id.slice(1);
}

function lines(...parts: (string | string[])[]): string {
	return `${parts.flat().join("\n")}\n`;
}

/** The heading and, when the screen can go back, the Back button every screen starts with. */
function screenHeader(screen: Screen): string[] {
	return [
		'      {onBack !== undefined && <Button title="Back" onPress={onBack} />}',
		`      <Text style={styles.title}>{${quoted(screen.title)}}</Text>`,
	];
}

const SCREEN_PROPS = "{ onBack }: { onBack?: () => void }";

const BASE_STYLES = [
	"  root: {",
	"    flex: 1,",
	"    padding: 16,",
	"  },",
	"  title: {",
	"    color: '#111111',",
	"    fontSize: 22,",
	"    fontWeight: '600',",
	"    marginBottom: 12,",
	"  },",
];

function counter(screen: CounterScreen): string {
	const name = componentName(screen);
	return lines(
		GENERATED,
		"import { useState } from 'react';",
		"import { Button, StyleSheet, Text, View } from 'react-native';",
		"",
		`export function ${name}(${SCREEN_PROPS}) {`,
		"  const [count, setCount] = useState(0);",
		"  return (",
		"    <View style={styles.root}>",
		screenHeader(screen),
		"      <Text style={styles.count}>Count: {count}</Text>",
		`      <Button title={${
			quoted(`Add ${screen.step}`)
		}} onPress={() => setCount(count + ${screen.step})} />`,
		"    </View>",
		"  );",
		"}",
		"",
		"const styles = StyleSheet.create({",
		BASE_STYLES,
		"  count: {",
		"    color: '#111111',",
		"    fontSize: 18,",
		"    marginBottom: 12,",
		"  },",
		"});",
	);
}

function list(screen: ListScreen): string {
	const name = componentName(screen);
	return lines(
		GENERATED,
		"import { Button, ScrollView, StyleSheet, Text, View } from 'react-native';",
		"",
		"const ROWS = [",
		screen.rows.map((row) =>
			`  { title: ${quoted(row.title)}, subtitle: ${quoted(row.subtitle)} },`
		),
		"];",
		"",
		`export function ${name}(${SCREEN_PROPS}) {`,
		"  return (",
		"    <ScrollView contentContainerStyle={styles.root}>",
		screenHeader(screen),
		"      {ROWS.map((row) => (",
		"        <View key={row.title} style={styles.row}>",
		"          <Text style={styles.rowTitle}>{row.title}</Text>",
		"          <Text style={styles.rowSubtitle}>{row.subtitle}</Text>",
		"        </View>",
		"      ))}",
		"    </ScrollView>",
		"  );",
		"}",
		"",
		"const styles = StyleSheet.create({",
		BASE_STYLES,
		"  row: {",
		"    paddingVertical: 8,",
		"    borderBottomWidth: StyleSheet.hairlineWidth,",
		"    borderBottomColor: '#DDDDDD',",
		"  },",
		"  rowTitle: {",
		"    color: '#111111',",
		"    fontSize: 16,",
		"  },",
		"  rowSubtitle: {",
		"    color: '#555555',",
		"    fontSize: 13,",
		"  },",
		"});",
	);
}

function form(screen: FormScreen): string {
	const name = componentName(screen);
	const fields = screen.fields;
	const initial = fields.map((field) => `${field.name}: ''`).join(", ");
	const saved = fields.map((field) => `\${values.${field.name}}`).join(", ");
	return lines(
		GENERATED,
		"import { useState } from 'react';",
		"import { Button, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';",
		"",
		`export function ${name}(${SCREEN_PROPS}) {`,
		`  const [values, setValues] = useState({ ${initial} });`,
		"  const [messages, setMessages] = useState<string[]>([]);",
		"",
		"  const submit = () => {",
		"    const errors: string[] = [];",
		fields.map((field) =>
			[
				`    if (values.${field.name}.length < ${field.minLength}) {`,
				`      errors.push(${
					quoted(`${field.label} needs at least ${field.minLength} characters`)
				});`,
				"    }",
			].join("\n")
		),
		`    setMessages(errors.length > 0 ? errors : [\`Saved: ${saved}\`]);`,
		"  };",
		"",
		"  return (",
		'    <ScrollView contentContainerStyle={styles.root} keyboardShouldPersistTaps="handled">',
		screenHeader(screen),
		fields.map((field) =>
			[
				"      <View style={styles.field}>",
				`        <Text style={styles.label}>{${quoted(field.label)}}</Text>`,
				"        <TextInput",
				"          style={styles.input}",
				`          value={values.${field.name}}`,
				`          onChangeText={(text) => setValues({ ...values, ${field.name}: text })}`,
				"        />",
				"      </View>",
			].join("\n")
		),
		`      <Button title={${quoted(screen.submitLabel)}} onPress={submit} />`,
		"      {messages.map((message) => (",
		"        <Text key={message} style={styles.message}>",
		"          {message}",
		"        </Text>",
		"      ))}",
		"    </ScrollView>",
		"  );",
		"}",
		"",
		"const styles = StyleSheet.create({",
		BASE_STYLES,
		"  field: {",
		"    marginBottom: 12,",
		"  },",
		"  label: {",
		"    color: '#111111',",
		"    fontSize: 14,",
		"    marginBottom: 4,",
		"  },",
		"  input: {",
		"    borderWidth: 1,",
		"    borderColor: '#999999',",
		"    color: '#111111',",
		"    padding: 8,",
		"  },",
		"  message: {",
		"    color: '#111111',",
		"    marginTop: 8,",
		"  },",
		"});",
	);
}

function detail(screen: DetailScreen): string {
	const name = componentName(screen);
	return lines(
		GENERATED,
		"import { Button, ScrollView, StyleSheet, Text } from 'react-native';",
		"",
		"const PARAGRAPHS = [",
		screen.paragraphs.map((paragraph) => `  ${quoted(paragraph)},`),
		"];",
		"",
		`export function ${name}(${SCREEN_PROPS}) {`,
		"  return (",
		"    <ScrollView contentContainerStyle={styles.root}>",
		screenHeader(screen),
		"      {PARAGRAPHS.map((paragraph) => (",
		"        <Text key={paragraph} style={styles.paragraph}>",
		"          {paragraph}",
		"        </Text>",
		"      ))}",
		"    </ScrollView>",
		"  );",
		"}",
		"",
		"const styles = StyleSheet.create({",
		BASE_STYLES,
		"  paragraph: {",
		"    color: '#111111',",
		"    fontSize: 15,",
		"    lineHeight: 22,",
		"    marginBottom: 12,",
		"  },",
		"});",
	);
}

function screenSource(screen: Screen): string {
	switch (screen.kind) {
		case "counter":
			return counter(screen);
		case "list":
			return list(screen);
		case "form":
			return form(screen);
		case "detail":
			return detail(screen);
	}
}

const ROOT_STYLE = [
	"  root: {",
	"    flex: 1,",
	"    backgroundColor: '#FFFFFF',",
	"  },",
];

const MENU_STYLES = [
	"  menu: {",
	"    padding: 16,",
	"  },",
	"  title: {",
	"    color: '#111111',",
	"    fontSize: 24,",
	"    fontWeight: '600',",
	"    marginBottom: 12,",
	"  },",
];

/** One screen renders directly: no menu and no Back button. */
function singleScreenApp(screen: Screen): string {
	const name = componentName(screen);
	return lines(
		GENERATED,
		"import { StyleSheet } from 'react-native';",
		"import { SafeAreaProvider, SafeAreaView } from 'react-native-safe-area-context';",
		`import { ${name} } from './src/screens/${name}';`,
		"",
		"export function App() {",
		"  return (",
		"    <SafeAreaProvider>",
		"      <SafeAreaView style={styles.root}>",
		`        <${name} />`,
		"      </SafeAreaView>",
		"    </SafeAreaProvider>",
		"  );",
		"}",
		"",
		"const styles = StyleSheet.create({",
		ROOT_STYLE,
		"});",
	);
}

function menuApp(app: TierApp): string {
	return lines(
		GENERATED,
		"import { useState } from 'react';",
		"import { Button, ScrollView, StyleSheet, Text } from 'react-native';",
		"import { SafeAreaProvider, SafeAreaView } from 'react-native-safe-area-context';",
		app.screens.map((screen) =>
			`import { ${componentName(screen)} } from './src/screens/${
				componentName(screen)
			}';`
		),
		"",
		"type ScreenId =",
		app.screens.map((screen, index) =>
			`  | ${quoted(screen.id)}${index === app.screens.length - 1 ? ";" : ""}`
		),
		"",
		"const MENU: { id: ScreenId; title: string }[] = [",
		app.screens.map((screen) =>
			`  { id: ${quoted(screen.id)}, title: ${quoted(screen.title)} },`
		),
		"];",
		"",
		"/** The current screen is state; null is the home menu. */",
		"export function App() {",
		"  const [screen, setScreen] = useState<ScreenId | null>(null);",
		"  const back = () => setScreen(null);",
		"  return (",
		"    <SafeAreaProvider>",
		"      <SafeAreaView style={styles.root}>",
		"        {screen === null ? (",
		"          <ScrollView contentContainerStyle={styles.menu}>",
		`            <Text style={styles.title}>{${quoted(app.title)}}</Text>`,
		"            {MENU.map((item) => (",
		"              <Button key={item.id} title={item.title} onPress={() => setScreen(item.id)} />",
		"            ))}",
		"          </ScrollView>",
		"        ) : (",
		"          renderScreen(screen, back)",
		"        )}",
		"      </SafeAreaView>",
		"    </SafeAreaProvider>",
		"  );",
		"}",
		"",
		"function renderScreen(screen: ScreenId, onBack: () => void) {",
		"  switch (screen) {",
		app.screens.map((screen) =>
			`    case ${quoted(screen.id)}:\n      return <${
				componentName(screen)
			} onBack={onBack} />;`
		),
		"  }",
		"}",
		"",
		"const styles = StyleSheet.create({",
		ROOT_STYLE,
		MENU_STYLES,
		"});",
	);
}

export const emitter: TierEmitter = {
	framework: "react-native",
	async emit(app: TierApp, projectDir: string): Promise<void> {
		const screensDir = `${projectDir}/src/screens`;
		await Deno.remove(screensDir, { recursive: true }).catch(
			(error: unknown) => {
				if (!(error instanceof Deno.errors.NotFound)) throw error;
			},
		);
		await Deno.mkdir(screensDir, { recursive: true });
		for (const screen of app.screens) {
			await Deno.writeTextFile(
				`${screensDir}/${componentName(screen)}.tsx`,
				screenSource(screen),
			);
		}
		const source = app.screens.length === 1
			? singleScreenApp(app.screens[0])
			: menuApp(app);
		await Deno.writeTextFile(`${projectDir}/App.tsx`, source);
	},
};
